import React from 'react';

const QuestionItem = ({
    question,
    numbering,
    onUpdate,
    onDelete,
    onAddChild,
}) => {
    return (
        <div className="border rounded-xl p-5 mb-5 bg-gray-50 shadow-sm">

            {/* Question Number */}
            <div className="flex items-center gap-2 mb-4">

                <span className="bg-blue-500 text-white px-3 py-1 rounded-full text-sm">
                    {numbering}
                </span>

                <span className="font-semibold text-gray-700">
                    Question
                </span>

            </div>

            {/* Question Input + Type */}
            <div className="grid md:grid-cols-2 gap-4">

                <input
                    type="text"
                    placeholder="Enter Question"
                    value={question.text}
                    onChange={(e) =>
                        onUpdate(question.id, {
                            text: e.target.value,
                        })
                    }
                    className="border p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400"
                />

                <select
                    value={question.type}
                    onChange={(e) =>
                        onUpdate(question.id, {
                            type: e.target.value,
                            answer: '',
                        })
                    }
                    className="border p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400"
                >
                    <option>Short Answer</option>
                    <option>True/False</option>
                </select>

            </div>

            {/* True False Answer */}
            {question.type === 'True/False' && (
                <div className="mt-4">

                    <label className="mr-3 font-medium">
                        Correct Answer:
                    </label>

                    <select
                        value={question.answer}
                        onChange={(e) =>
                            onUpdate(question.id, {
                                answer: e.target.value,
                            })
                        }
                        className="border p-2 rounded-lg"
                    >
                        <option value="">Select</option>
                        <option value="True">True</option>
                        <option value="False">False</option>
                    </select>

                </div>
            )}

            {/* Action Buttons */}
            <div className="flex gap-3 mt-5 flex-wrap">
                {/* Delete */}
                <button
                    onClick={() => onDelete(question.id)}
                    className="bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg transition"
                >
                    Delete
                </button>
                {/* Add Child */}
                <button
                    onClick={() => onAddChild(question.id)}
                    className="bg-purple-500 hover:bg-purple-600 text-white px-4 py-2 rounded-lg transition"
                >
                    Add Follow-up Question
                </button>



            </div>

            {/* Child Questions */}
            {question.children.length > 0 && (
                <div className="ml-8 mt-6 border-l-4 pl-5 border-blue-300">

                    {question.children.map((child, index) => (
                        <QuestionItem
                            key={child.id}
                            question={child}
                            numbering={`${numbering}.${index + 1}`}
                            onUpdate={onUpdate}
                            onDelete={onDelete}
                            onAddChild={onAddChild}
                        />
                    ))}

                </div>
            )}

        </div>
    );
};

export default QuestionItem;
